g: 48px 28px; }.form-wrap { width: min(100%, 460px); }.form-heading { margin-bottom: 32px; }.form-heading .eyebrow { color: #128761; }.form-heading h2 { margin: 0; color: #132b23; font-size: 2rem; line-height: 1.13; letter-spacing: -.045em; }.form-heading > p:last-child { margin: 10px 0 0; color: #6b8177; font-size: .92rem; }.register-form { display: grid; gap: 18px; }.field { display: grid; gap: 7px; }.field label { color: #29463a; font-size: .8rem; font-weight: 750; }.field input { width: 100%; height: 48px; padding: 0 13px; color: #19352a; background: #fff; border: 1px solid #d8e6df; border-radius: 11px; outline: none; transition: border .18s, box-shadow .18s; }.field input::placeholder { color: #9aaca3; }.field input:focus { border-color: #16986d; box-shadow: 0 0 0 4px rgba(22,152,109,.11); }.field input.error { border-color: #e15858; }.password-wrap { position: relative; }.password-wrap input { padding-right: 58px; }.show-password { position: absolute; top: 50%; right: 7px; padding: 5px 7px; color: #14815e; background: transparent; box-shadow: none; font-size: .72rem; font-weight: 800; transform: translateY(-50%); }.show-password:hover { color: #075d42; box-shadow: none; transform: translateY(-50%); }.field-error, .auth-error { color: #c33e45; font-size: .73rem; }.password-strength { display: grid; gap: 8px; padding: 11px 12px; background: #f2f8f5; border: 1px solid #dcece4; border-radius: 10px; }.password-strength > div { display: flex; justify-content: space-between; color: #527267; font-size: .73rem; }.password-strength strong.weak { color: #ce4a4f; }.password-strength strong.good { color: #bd7a13; }.password-strength strong.strong { color: #108359; }.strength-track { height: 5px; overflow: hidden; background: #dbe9e1; border-radius: 99px; }.strength-track i { display: block; height: 100%; border-radius: inherit; transition: width .2s; }.strength-track i.weak { background: #e15b5b; }.strength-track i.good { background: #e0a129; }.strength-track i.strong { background: #20a671; }.password-strength small { color: #718b80; font-size: .68rem; line-height: 1.4; }.terms { display: flex; align-items: flex-start; gap: 9px; color: #647d72; font-size: .76rem; line-height: 1.5; cursor: pointer; }.terms input { width: 16px; height: 16px; margin: 2px 0 0; accent-color: #14936a; }.terms a, .signin a { color: #087757; font-weight: 750; text-decoration: none; }.terms-error { margin-top: -12px; }.auth-error { margin: 0; padding: 10px 12px; background: #fff2f2; border-radius: 9px; }.submit-btn { height: 50px; display: grid; place-items: center; padding: 0 18px; color: white; background: linear-gradient(110deg, #087656, #18a878); border-radius: 11px; box-shadow: 0 10px 22px rgba(13,128,91,.18); font-size: .9rem; font-weight: 800; }.submit-btn:hover:not(:disabled) { box-shadow: 0 14px 28px rgba(13,128,91,.26); transform: translateY(-1px); }.submit-btn:disabled { opacity: .7; }.submit-btn b { margin-left: 7px; font-size: 1.1rem; }.loading { display: flex; align-items: center; gap: 8px; }.loading i { width: 14px; height: 14px; border: 2px solid rgba(255,255,255,.4); border-top-color: #fff; border-radius: 50%; animation: spin .75s linear infinite; }@keyframes spin { to { transform: rotate(360deg); } }.signin { margin: 25px 0 0; color: #738a7e; text-align: center; font-size: .8rem; }.modal-overlay { position: fixed; inset: 0; z-index: 2000; display: grid; place-items: center; padding: 20px; background: rgba(5,31,24,.56); backdrop-filter: blur(6px); }.success-modal { width: min(100%, 390px); padding: 34px; background: white; border-radius: 20px; box-shadow: 0 24px 70px rgba(0,0,0,.22); text-align: center; }.success-mark { width: 52px; height: 52px; display: grid; place-items: center; margin: 0 auto 17px; color: #087957; background: #e9f8f0; border-radius: 50%; font-size: 1.5rem; font-weight: 900; }.success-modal h3 { margin: 0; color: #17342a; font-size: 1.3rem; }.success-modal p { color: #60786d; font-size: .87rem; line-height: 1.6; }.success-